APPROVED_METADATA_ANCHOR = 'ce2e79c12c87aa3b52d1957faa62796636d7c531854b3c33fd9b9e3490629221'
APPROVED_SELF_AST = '294e8dd8355727224b4b861df15fc4b3299da0fedc131ea61901264f190ac865'

def certify_fixed_structural_lot_source() -> str:
    """Issue no source authority from caller hashes or an unreviewed inventory."""
    root = Path(__file__).resolve().parents[2]
    own = root / 'src/backend/backtest_fixed_structural_lot_certification_v20.py'
    try:
        own_source = own.read_text(encoding='utf-8')
        tree = ast.parse(own_source)
    except (OSError, SyntaxError) as exc:
        raise ValueError('Fixed-lot source certifier cannot be read') from exc
    names = ('REQUIRED_SOURCE_FILES', 'REVIEWED_SOURCE_AST', 'APPROVED_METADATA_ANCHOR', 'APPROVED_SELF_AST')
    if len(tree.body) != 10 or not isinstance(tree.body[0], ast.Expr) or (not isinstance(tree.body[0].value, ast.Constant)) or (tree.body[0].value.value != __doc__) or ([ast.unparse(n) for n in tree.body[1:5]] != ['import ast', 'from hashlib import sha256', 'import json', 'from pathlib import Path']) or any((type(n) is not ast.Assign or len(n.targets) != 1 or type(n.targets[0]) is not ast.Name or (n.targets[0].id != name) for n, name in zip(tree.body[5:9], names))) or (type(tree.body[9]) is not ast.FunctionDef) or (tree.body[9].name != 'certify_fixed_structural_lot_source') or tree.body[9].decorator_list or tree.body[9].args.posonlyargs or tree.body[9].args.args or tree.body[9].args.kwonlyargs or tree.body[9].args.vararg or tree.body[9].args.kwarg:
        raise ValueError('Fixed-lot certifier module envelope differs')
    try:
        fresh = {name: ast.literal_eval(n.value) for name, n in zip(names, tree.body[5:9])}
    except (ValueError, TypeError) as exc:
        raise ValueError('Fixed-lot certifier declarations are not literal') from exc
    loaded = dict(zip(names, (REQUIRED_SOURCE_FILES, REVIEWED_SOURCE_AST, APPROVED_METADATA_ANCHOR, APPROVED_SELF_AST)))
    if fresh != loaded:
        raise ValueError('Fixed-lot loaded and fresh declarations differ')
    required = REQUIRED_SOURCE_FILES
    if type(required) is not tuple or not required or any((type(p) is not str or not p.startswith(('src/', 'pipelines/', 'scripts/', 'research/')) or '..' in p.split('/') or ('\\' in p) or (not p.endswith('.py')) for p in required)) or (len(set(required)) != len(required)):
        raise ValueError('Fixed-lot required source inventory is malformed')
    if type(REVIEWED_SOURCE_AST) is not dict:
        raise ValueError('Fixed-lot reviewed source pins must be an exact map')
    if not REVIEWED_SOURCE_AST and (not APPROVED_METADATA_ANCHOR) and (not APPROVED_SELF_AST):
        raise ValueError('Fixed-lot source seal is unapproved; admission remains closed')
    if tuple(REVIEWED_SOURCE_AST) != required:
        raise ValueError('Fixed-lot reviewed source keyset or order differs')
    pins = (*REVIEWED_SOURCE_AST.values(), APPROVED_METADATA_ANCHOR, APPROVED_SELF_AST)
    if any((type(v) is not str or len(v) != 64 or any((c not in '0123456789abcdef' for c in v)) for v in pins)):
        raise ValueError('Fixed-lot source pins are malformed')
    metadata = {'required': required, 'sources': REVIEWED_SOURCE_AST}
    if sha256(json.dumps(metadata, sort_keys=True, separators=(',', ':')).encode()).hexdigest() != APPROVED_METADATA_ANCHOR:
        raise ValueError('Fixed-lot source metadata anchor differs')
    if sha256(ast.unparse(tree.body[9]).encode()).hexdigest() != APPROVED_SELF_AST:
        raise ValueError('Fixed-lot certifier function source differs')
    observed = [('certifier_function', APPROVED_SELF_AST), ('certifier_metadata', APPROVED_METADATA_ANCHOR)]
    sealed_sources = []
    for relative in required:
        path = root / relative
        if not path.is_file() or path.is_symlink() or root not in path.resolve().parents:
            raise ValueError('Fixed-lot required source path is missing or foreign: ' + relative)
        try:
            source = path.read_text(encoding='utf-8')
            selected = ast.parse(source)
        except (OSError, SyntaxError) as exc:
            raise ValueError('Fixed-lot required source cannot be parsed: ' + relative) from exc
        if sha256(ast.unparse(selected).encode()).hexdigest() != REVIEWED_SOURCE_AST[relative]:
            raise ValueError('Fixed-lot reviewed source authority changed: ' + relative)
        observed.append((relative, sha256(source.encode()).hexdigest()))
        sealed_sources.append((path, source))
    # Preserve the approved99 whole-module pins. Fresh, currently sealed
    # declarations are read from source rather than accepting a caller map.
    from .backtest_fixed_structural_lot_compatibility_v20 import restore_reviewed_parent_source as restore_current
    from .backtest_declared_waiting_ladder_compatibility import restore_reviewed_parent_source as restore_waiting
    prior_path = root / 'src/backend/backtest_fixed_structural_lot_certification_v19.py'
    prior_source = prior_path.read_text(encoding='utf-8')
    prior_tree = ast.parse(prior_source)
    maps = [n for n in prior_tree.body if type(n) is ast.Assign and len(n.targets) == 1
            and type(n.targets[0]) is ast.Name and n.targets[0].id == 'REVIEWED_SOURCE_AST']
    if len(maps) != 1:
        raise ValueError('Retained99 reviewed source declarations differ')
    for relative, expected in ast.literal_eval(maps[0].value).items():
        path = root / relative
        source = path.read_text(encoding='utf-8')
        restored = restore_waiting(restore_current(source, relative), relative)
        if sha256(ast.unparse(ast.parse(restored)).encode()).hexdigest() != expected:
            raise ValueError('Retained99 exact source restoration differs: ' + relative)
        sealed_sources.append((path, source))
    sealed_sources.append((prior_path, prior_source))
    if any((path.read_text(encoding='utf-8') != source for path, source in sealed_sources)):
        raise ValueError('Fixed-lot source changed during certification')
    if own.read_text(encoding='utf-8') != own_source:
        raise ValueError('Fixed-lot certifier changed during certification')
    return sha256(json.dumps(observed, separators=(',', ':')).encode()).hexdigest()
